actions.script:
import org.moqui.context.ExecutionContext
ExecutionContext ec = context.ec
def res = [:]
boolean _d = ec.artifactExecution.disableAuthz()
try {
    int horizon = (horizonDays ?: 14) as int
    int leadTime = (leadTimeDays ?: 7) as int
    double sl = (serviceLevel ?: 0.95) as double
    if (horizon < 1) horizon = 14
    if (horizon > 120) horizon = 120
    if (leadTime < 1) leadTime = 7

    def orgId = organizationPartyId ?: ec.user.getPreference("ACTIVE_ORGANIZATION")
    if (!orgId) { summary = "No active organization in context; cannot forecast."; result = res; return }

    def prod = null
    if (productId) prod = ec.entity.find("mantle.product.Product").condition("productId", productId).condition("ownerPartyId", orgId).one()
    if (!prod && productName) {
        def pl = ec.entity.find("mantle.product.Product").condition("ownerPartyId", orgId)
            .condition("productName", "like", "%" + productName + "%").orderBy("productName").limit(1).list()
        if (pl) prod = pl[0]
    }
    if (!prod) { summary = "I could not find a product called '" + (productName ?: productId) + "' in your catalog. Please double-check the spelling, or tell me the exact product name, and I will get its forecast."; result = res; return }
    def pid = prod.productId
    def pname = prod.productName

    def txnDate = [:]
    ec.entity.find("zenith.erp.pos.PosTransaction").condition("organizationPartyId", orgId)
        .selectField("transactionId").selectField("entryDate").list().each {
            if (it.entryDate != null) txnDate[it.transactionId] = it.entryDate.toLocalDateTime().toLocalDate()
        }
    def daily = [:]
    ec.entity.find("zenith.erp.pos.PosTransactionItem").condition("productId", pid)
        .selectField("transactionId").selectField("quantity").list().each {
            def ld = txnDate[it.transactionId]
            if (ld != null) { double q = (it.quantity ?: 0) as double; daily[ld] = ((daily[ld] ?: 0.0d) as double) + q }
        }
    if (daily.isEmpty()) { summary = "No sales history found for '" + pname + "', so a demand forecast cannot be produced yet."; result = [productName: pname]; return }

    def dts = new ArrayList(daily.keySet()); Collections.sort(dts)
    def minD = dts.get(0); def maxD = dts.get(dts.size()-1)
    def series = []
    def cur = minD
    while (!cur.isAfter(maxD)) { series.add(((daily[cur] ?: 0.0d) as double)); cur = cur.plusDays(1) }
    int n = series.size()

    // ROBUST anti-spike: clip one-off outlier days at 4x the typical selling-day volume (median of
    // positive days), so a single bulk order / spike week can't inflate the mean, tilt the trend, or be
    // repeated by seasonal-naive. Sustained increases survive (many high days -> high median -> high cap);
    // real spikes are still flagged separately by the demand-shift detector on RAW data. (ZE-CP-E-02d)
    def _pos = []; for (v in series) { double _dv = v as double; if (_dv > 0.0) _pos.add(_dv) }
    if (_pos.size() >= 4) {
        Collections.sort(_pos); int _ps = _pos.size(); int _half = _ps.intdiv(2)
        double _med = (_ps % 2 == 1) ? ((double)_pos[_half]) : (((double)_pos[_half - 1] + (double)_pos[_half]) / 2.0)
        double _cap = 4.0 * _med
        if (_cap > 0.0) { for (int _i = 0; _i < n; _i++) { if (((double)series[_i]) > _cap) series[_i] = _cap } }
    }

    double sum = 0.0; for (v in series) sum += v
    double mean = sum / n
    double varSum = 0.0; for (v in series) varSum += (v - mean) * (v - mean)
    double sd = Math.sqrt(varSum / Math.max(1, n - 1))
    double _phi = 0.85                      // trend damping factor, shared by forecast + its back-test

    def fit = { int len ->
        double sx=0, sy=0, sxx=0, sxy=0
        for (int i = 0; i < len; i++) { sx += i; sy += series[i]; sxx += i*i; sxy += i*series[i] }
        double den = (len*sxx - sx*sx)
        double slope = den != 0 ? (len*sxy - sx*sy) / den : 0.0
        double intercept = (sy - slope*sx) / len
        double mn = sy / len
        double[] ds = new double[7]; int[] dc = new int[7]; def c = minD
        for (int i = 0; i < len; i++) { int dw = c.getDayOfWeek().getValue() % 7; ds[dw] += series[i]; dc[dw]++; c = c.plusDays(1) }
        double[] df = new double[7]
        for (int k = 0; k < 7; k++) { double a = dc[k] > 0 ? ds[k]/dc[k] : mn; df[k] = mn > 0 ? Math.max(0.3, Math.min(2.5, a/mn)) : 1.0 }
        return [intercept, slope, df, mn]
    }

    // predictors: trained on [0,trainEnd), predict day index i.
    // predA back-tests the SAME damped-trend-shrunk-to-mean model the forecast uses, so the
    // reported confidence describes the forecast actually shown (not a different raw-trend model). (ZE-CP-E-02c)
    def predA = { int trainEnd, int i ->
        def f = fit(trainEnd)
        double fi = (double)f[0]; double fs = (double)f[1]; double[] fdf = (double[])f[2]; double fmn = (double)f[3]
        double fL = fi + fs*(trainEnd - 1); int hstep = i - trainEnd + 1
        double dmp = _phi * (1.0 - Math.pow(_phi, hstep)) / (1.0 - _phi)
        double lvl = Math.max(0.0, fL + fs*dmp); double base = 0.5*lvl + 0.5*fmn
        int dw = minD.plusDays(i).getDayOfWeek().getValue()%7
        return Math.max(0.0, base * fdf[dw])
    }
    // seasonal-naive, ALSO shrunk toward the training mean so a single spike/trough week can't drag
    // the forecast to a wild value (mirrors the trend branch; keeps whichever method wins well-behaved). (ZE-CP-E-02b)
    def predB = { int trainEnd, int i -> double s=0; for(int k=0;k<trainEnd;k++) s+=series[k]; double tm = trainEnd>0 ? s/trainEnd : 0.0; double sn = (i >= 7) ? series[i-7] : tm; return 0.5*sn + 0.5*tm }

    def cv = { Closure pred ->
        int period = 7; int periods = (int)(n / period)
        if (periods < 3) return null
        int testCount = Math.min(4, periods - 1)
        // WAPE (total error / total actual across the test weeks) rather than an average of per-week
        // APEs: a single low-volume week can't dominate via a tiny denominator, so the score reflects
        // real fit quality and varies instead of pinning at a floor. (ZE-CP-E-02c)
        double sumAbs = 0.0; double sumAct = 0.0
        for (int p = periods - testCount; p < periods; p++) {
            int trainEnd = p * period; if (trainEnd < period) continue
            double predTot = 0.0, actTot = 0.0
            for (int i = trainEnd; i < trainEnd + period && i < n; i++) { predTot += Math.max(0.0, pred(trainEnd, i)); actTot += series[i] }
            sumAbs += Math.abs(actTot - predTot); sumAct += actTot
        }
        if (sumAct <= 0) return null
        double wape = sumAbs / sumAct; return Math.max(1, Math.min(96, (int)Math.round(100.0*(1.0 - wape))))
    }

    Integer accA = cv(predA); Integer accB = cv(predB)
    boolean useB = (accB != null) && (accA == null || accB > accA)
    Integer confidence = useB ? accB : accA

    def full = fit(n)
    double intercept = full[0]; double slope = full[1]; double[] dowF = full[2]
    def dowNames = ["Sun","Mon","Tue","Wed","Thu","Fri","Sat"]
    int peakDow = 0; for (int k = 1; k < 7; k++) if (dowF[k] > dowF[peakDow]) peakDow = k

    // horizon forecast using the chosen method
    // Trend branch: DAMPED linear trend (Gardner) shrunk toward the historical mean, so a
    // declining series levels off near typical demand instead of collapsing to ~0, and a rising
    // one is pulled back toward its average instead of extrapolating without bound. (ZE-CP-E-02b)
    double _L = intercept + slope*(n - 1)   // fitted level at the last observed day (_phi defined above)
    double fTotal = 0.0; def fcur = maxD.plusDays(1)
    for (int h = 0; h < horizon; h++) {
        double f
        if (useB) { double _sn = (n >= 7) ? series[n - 7 + (h % 7)] : mean; f = 0.5*_sn + 0.5*mean }
        else {
            int dw = fcur.getDayOfWeek().getValue() % 7
            double _damp = _phi * (1.0 - Math.pow(_phi, h + 1)) / (1.0 - _phi)
            double _lvl = Math.max(0.0, _L + slope*_damp)   // damped trend level
            double _base = 0.5*_lvl + 0.5*mean              // shrink toward historical mean
            f = Math.max(0.0, _base * dowF[dw])
        }
        fTotal += Math.max(0.0, f); fcur = fcur.plusDays(1)
    }
    String methodLabel = useB ? "seasonal-naive (last week)" : "trend + weekly seasonality"
    String methodEnum = useB ? "FmSeasonal" : "FmExponential"

    double z = sl >= 0.99 ? 2.33 : (sl >= 0.975 ? 1.96 : (sl >= 0.95 ? 1.645 : (sl >= 0.90 ? 1.28 : 1.04)))
    double safety = z * sd * Math.sqrt((double) leadTime)
    double dailyDemand = (fTotal / (double) horizon)   // representative daily rate, consistent with the shown forecast
    double rop = dailyDemand * leadTime + safety
    double suggestedOrder = fTotal + safety

    def r2 = { double v -> (Math.round(v*100.0)/100.0) }
    // plain-language reliability band so a genuinely low back-tested % reads as "rough guide", not a broken default (ZE-CP-E-02c)
    def confBand = { Integer c -> c == null ? null : (c >= 75 ? "high" : (c >= 55 ? "good" : (c >= 40 ? "moderate" : (c >= 25 ? "low" : "very rough")))) }
    def trendTxt = slope > 0.02 ? "rising" : (slope < -0.02 ? "declining" : "stable")
    res = [
        productName: pname, productId: pid,
        historyDays: n, avgDailyDemand: r2(mean), trendPerDay: r2(slope), peakWeekday: dowNames[peakDow],
        horizonDays: horizon, forecastDemand: (int)Math.round(fTotal),
        leadTimeDays: leadTime, serviceLevel: sl,
        reorderPoint: (int)Math.round(rop), safetyStock: (int)Math.round(safety),
        suggestedOrderQty: (int)Math.round(suggestedOrder),
        confidencePct: confidence, method: methodLabel, methodEnumId: methodEnum
    ]
    summary = "For '" + pname + "', expect about " + ((int)Math.round(fTotal)) + " units over the next " + horizon + " days" +
        " (around " + String.format("%.1f", fTotal / (double) horizon) + " a day, a " + trendTxt + " trend, busiest on " + dowNames[peakDow] + "). " +
        "At " + ((int)Math.round(sl*100)) + "% service level with a " + leadTime + "-day lead time, reorder at about " + ((int)Math.round(rop)) +
        " units (incl. ~" + ((int)Math.round(safety)) + " safety stock), and order about " + ((int)Math.round(suggestedOrder)) + " units. " +
        (confidence != null ? ("Confidence ~" + confidence + "% (" + confBand(confidence) + ") using the " + methodLabel + " method") : "Confidence limited by short history") +
        ", based on " + n + " days of real sales."
    result = res
} catch (Exception e) {
    ec.logger.error("forecast#ProductDemand failed: " + e.message, e)
    summary = "The forecast could not be completed due to a data error."; result = res
} finally { if (!_d) ec.artifactExecution.enableAuthz() }

import org.moqui.context.ExecutionContext
ExecutionContext ec = context.ec
boolean _d = ec.artifactExecution.disableAuthz()
int prc = 0, cal = 0, fc = 0, alerts = 0
try {
    int period = (periodDays ?: 7) as int; if (period < 1) period = 7
    int top = (topN ?: 50) as int
    def today = ec.user.nowTimestamp.toLocalDateTime().toLocalDate()
    def todaySql = java.sql.Date.valueOf(today)
    def orgs = []
    if (organizationPartyId) orgs.add(organizationPartyId)
    else ec.entity.find("zenith.erp.saas.SaasTenant").condition("statusId","SaasTenantActive").selectField("organizationPartyId").list().each { if (it.organizationPartyId) orgs.add(it.organizationPartyId) }

    for (org in orgs) {
        def topRows = ec.entity.find("zenith.erp.pos.ProductDemandView").condition("organizationPartyId", org).orderBy("-unitsSold").limit(top).list()
        if (!topRows) continue
        def txnDate = [:]
        ec.entity.find("zenith.erp.pos.PosTransaction").condition("organizationPartyId", org).selectField("transactionId").selectField("entryDate").list().each { if (it.entryDate != null) txnDate[it.transactionId] = it.entryDate.toLocalDateTime().toLocalDate() }
        // category maps for category-level demand aggregation/detection
        def catOfProduct = [:]; def catNameMap = [:]; def catDaily = [:]
        ec.entity.find("mantle.product.category.ProductCategoryMember").selectField("productCategoryId").selectField("productId").list().each { if (it.productId != null && !catOfProduct.containsKey(it.productId)) catOfProduct[it.productId] = it.productCategoryId }
        ec.entity.find("mantle.product.category.ProductCategory").selectField("productCategoryId").selectField("categoryName").list().each { catNameMap[it.productCategoryId] = it.categoryName }
        for (row in topRows) {
            def pid = row.productId; if (!pid) continue
            prc++
            // product's daily sales map (shared by calibration + anomaly detection)
            def prodDaily = [:]
            ec.entity.find("zenith.erp.pos.PosTransactionItem").condition("productId", pid).selectField("transactionId").selectField("quantity").list().each {
                def ld = txnDate[it.transactionId]; if (ld != null) { double q = (it.quantity ?: 0) as double; prodDaily[ld] = ((prodDaily[ld] ?: 0.0d) as double) + q }
            }
            // accumulate into this product's category (for category-level detection after the loop)
            def _cat = catOfProduct[pid]
            if (_cat != null) { def cd = catDaily[_cat]; if (cd == null) { cd = [:]; catDaily[_cat] = cd }; prodDaily.each { k, v -> cd[k] = ((cd[k] ?: 0.0d) as double) + (v as double) } }
            // ---- 1) calibrate past-due forecasts for this product ----
            def due = ec.entity.find("zenith.erp.inventory.DemandForecast").condition("productId", pid)
                .condition("periodEnd", "<", todaySql).list().findAll { it.accuracyPercent == null && it.periodStart != null && it.periodEnd != null }
            if (due) {
                for (f in due) {
                    def ps = f.periodStart instanceof java.sql.Date ? f.periodStart.toLocalDate() : f.periodStart
                    def pe = f.periodEnd instanceof java.sql.Date ? f.periodEnd.toLocalDate() : f.periodEnd
                    double act = 0.0; def c = ps
                    while (c != null && !c.isAfter(pe)) { act += ((prodDaily[c] ?: 0.0d) as double); c = c.plusDays(1) }
                    double fq = (f.forecastQuantity ?: 0) as double
                    Integer acc = act > 0 ? Math.max(0, Math.min(100, (int)Math.round(100.0*(1.0 - Math.abs(fq - act)/act)))) : (fq > 0 ? 0 : 100)
                    f.actualQuantity = act; f.accuracyPercent = acc; f.update(); cal++
                }
            }
            // ---- 1b) demand-shift anomaly detection (threshold = 2 sigma of the product's own daily volatility) ----
            try {
                if (prodDaily.size() >= 2) {
                    def adts = new ArrayList(prodDaily.keySet()); Collections.sort(adts)
                    def amin = adts.get(0); def amax = adts.get(adts.size()-1)
                    def aser = []; def ac = amin
                    while (!ac.isAfter(amax)) { aser.add(((prodDaily[ac] ?: 0.0d) as double)); ac = ac.plusDays(1) }
                    int an = aser.size()
                    if (an >= 14) {
                        int rc = 7
                        double rSum = 0.0; for (int i = an-rc; i < an; i++) rSum += aser[i]; double recentAvg = rSum / rc
                        int bn = an - rc; double bSum = 0.0; for (int i = 0; i < bn; i++) bSum += aser[i]; double baseAvg = bSum / bn
                        double bVar = 0.0; for (int i = 0; i < bn; i++) bVar += (aser[i]-baseAvg)*(aser[i]-baseAvg); double baseStd = Math.sqrt(bVar / Math.max(1, bn-1))
                        if (baseAvg >= 1.0 && baseStd > 0.0001) {
                            double zc = (recentAvg - baseAvg) / baseStd
                            String dir = zc >= 2.0 ? "Increase" : (zc <= -2.0 ? "Decrease" : null)
                            if (dir != null) {
                                def dup = ec.entity.find("zenith.erp.inventory.DemandAlert").condition("productId", pid).condition("alertDate", todaySql).condition("alertType", "Shift").list()
                                if (!dup) {
                                    int pct = (int)Math.round(100.0*(recentAvg-baseAvg)/baseAvg)
                                    def pn = row.productName ?: pid
                                    String amsg = "Demand for '" + pn + "' has " + (dir=="Increase" ? "jumped" : "dropped") + " " + Math.abs(pct) + "% recently (last week about " + ((int)Math.round(recentAvg)) + "/day vs usual " + ((int)Math.round(baseAvg)) + "/day), beyond its normal range (" + (Math.round(zc*10)/10.0) + " sigma)."
                                    ec.service.sync().name("create#zenith.erp.inventory.DemandAlert").parameters([
                                        organizationPartyId: org, productId: pid, productName: pn, alertDate: todaySql, alertType: "Shift", direction: dir,
                                        recentAvgDaily: recentAvg, baselineAvgDaily: baseAvg, pctChange: pct, zScore: (Math.round(zc*100)/100.0),
                                        message: amsg, statusId: "AlertNew", createdStamp: ec.user.nowTimestamp
                                    ]).call()
                                    alerts++
                                    try {
                                        def uids = ec.entity.find("moqui.security.UserPreference").condition("preferenceKey","ACTIVE_ORGANIZATION").condition("preferenceValue", org).selectField("userId").list().collect { it.userId }.unique()
                                        for (uid in uids) {
                                            def nm = ec.makeNotificationMessage().topic("DemandAlert").title("Demand alert: " + pn).message([productName: pn, direction: dir, pctChange: pct, text: amsg])
                                            nm.userId(uid); nm.send()
                                        }
                                    } catch (Exception ne) { ec.logger.warn("DemandAlert notify failed: " + ne.message) }
                                }
                            }
                        }
                    }
                }
            } catch (Exception de) { ec.logger.warn("DemandAlert detection failed for " + pid + ": " + de.message) }

            // ---- 2) forecast (always, for reorder point) + store fresh forecast if none today ----
            def out = ec.service.sync().name("zenith.inventory.AdvancedForecastServices.forecast#ProductDemand").parameter("productId", pid).parameter("horizonDays", period).parameter("organizationPartyId", org).call()
            def r = out?.result
            if (r && r.forecastDemand != null) {
                double rop = (r.reorderPoint ?: 0) as double
                double ss = (r.safetyStock ?: 0) as double
                int sugg = (r.suggestedOrderQty ?: 0) as int
                def existing = ec.entity.find("zenith.erp.inventory.DemandForecast").condition("productId", pid).condition("periodStart", todaySql).list()
                if (!existing) {
                    ec.service.sync().name("create#zenith.erp.inventory.DemandForecast").parameters([
                        productId: pid, periodStart: todaySql, periodEnd: java.sql.Date.valueOf(today.plusDays(period)),
                        forecastQuantity: r.forecastDemand, forecastMethodEnumId: (r.methodEnumId ?: "FmSeasonal"), actualQuantity: null, accuracyPercent: null,
                        reorderPoint: rop, safetyStock: ss, suggestedOrderQty: sugg
                    ]).call()
                    fc++
                }
                // ---- 3) REORDER alert: delegate to shared check#ProductReorder (also used by the intraday cycle#ReorderCheck) ----
                try {
                    if (rop > 0) {
                        def rout = ec.service.sync().name("zenith.inventory.AdvancedForecastServices.check#ProductReorder").parameters([
                            organizationPartyId: org, productId: pid, productName: (row.productName ?: pid),
                            reorderPoint: rop, safetyStock: ss, suggestedOrderQty: sugg, alertDate: todaySql
                        ]).call()
                        if (rout?.alerted) alerts++
                    }
                } catch (Exception re) { ec.logger.warn("Reorder check failed for " + pid + ": " + re.message) }
            }
        }
        // ---- category-level demand-shift detection (aggregate of member products) ----
        try {
            catDaily.each { catId, cmap ->
                try {
                    if (cmap && cmap.size() >= 2) {
                        def cdts = new ArrayList(cmap.keySet()); Collections.sort(cdts)
                        def cmin = cdts.get(0); def cmax = cdts.get(cdts.size()-1)
                        def cser = []; def cc = cmin
                        while (!cc.isAfter(cmax)) { cser.add(((cmap[cc] ?: 0.0d) as double)); cc = cc.plusDays(1) }
                        int cn = cser.size()
                        if (cn >= 14) {
                            int rc2 = 7
                            double rS = 0.0; for (int i = cn-rc2; i < cn; i++) rS += cser[i]; double cRecent = rS / rc2
                            int cbn = cn - rc2; double bS = 0.0; for (int i = 0; i < cbn; i++) bS += cser[i]; double cBase = bS / cbn
                            double cV = 0.0; for (int i = 0; i < cbn; i++) cV += (cser[i]-cBase)*(cser[i]-cBase); double cStd = Math.sqrt(cV / Math.max(1, cbn-1))
                            if (cBase >= 1.0 && cStd > 0.0001) {
                                double cz = (cRecent - cBase) / cStd
                                String cdir = cz >= 2.0 ? "Increase" : (cz <= -2.0 ? "Decrease" : null)
                                if (cdir != null) {
                                    def cdup = ec.entity.find("zenith.erp.inventory.DemandAlert").condition("productId", catId).condition("alertDate", todaySql).condition("alertType", "CategoryShift").list()
                                    if (!cdup) {
                                        int cpct = (int)Math.round(100.0*(cRecent-cBase)/cBase)
                                        def cnm2 = catNameMap[catId] ?: catId
                                        String cmsg = "Category '" + cnm2 + "' demand has " + (cdir=="Increase" ? "jumped" : "dropped") + " " + Math.abs(cpct) + "% recently (last week about " + ((int)Math.round(cRecent)) + "/day vs usual " + ((int)Math.round(cBase)) + "/day), beyond its normal range (" + (Math.round(cz*10)/10.0) + " sigma)."
                                        ec.service.sync().name("create#zenith.erp.inventory.DemandAlert").parameters([
                                            organizationPartyId: org, productId: catId, productName: cnm2, alertDate: todaySql, alertType: "CategoryShift", direction: cdir,
                                            recentAvgDaily: cRecent, baselineAvgDaily: cBase, pctChange: cpct, zScore: (Math.round(cz*100)/100.0),
                                            message: cmsg, statusId: "AlertNew", createdStamp: ec.user.nowTimestamp
                                        ]).call()
                                        alerts++
                                        try {
                                            def uids2 = ec.entity.find("moqui.security.UserPreference").condition("preferenceKey","ACTIVE_ORGANIZATION").condition("preferenceValue", org).selectField("userId").list().collect { it.userId }.unique()
                                            for (uid in uids2) { def nm3 = ec.makeNotificationMessage().topic("DemandAlert").title("Category alert: " + cnm2).message([category: cnm2, direction: cdir, pctChange: cpct, text: cmsg]); nm3.userId(uid); nm3.send() }
                                        } catch (Exception cne) { ec.logger.warn("Category notify failed: " + cne.message) }
                                    }
                                }
                            }
                        }
                    }
                } catch (Exception cie) { ec.logger.warn("Category detect failed for " + catId + ": " + cie.message) }
            }
        } catch (Exception ce2) { ec.logger.warn("Category loop failed: " + ce2.message) }
    }
    productsProcessed = prc; calibrated = cal; created = fc; alertsCreated = alerts
    summary = "Forecast cycle done: " + prc + " products across " + orgs.size() + " tenant(s); calibrated " + cal + " finished forecasts against real sales; created " + fc + " new forecasts; raised " + alerts + " demand-shift alerts."
} catch (Exception e) {
    ec.logger.error("cycle#DemandForecast failed: " + e.message, e)
    productsProcessed = prc; calibrated = cal; created = fc; alertsCreated = alerts
    summary = "Forecast cycle hit an error after processing " + prc + " products: " + e.message
} finally { if (!_d) ec.artifactExecution.enableAuthz() }

import org.moqui.context.ExecutionContext
ExecutionContext ec = context.ec
alerted = false; direction = null
double rop = (reorderPoint ?: 0) as double
double ss = (safetyStock ?: 0) as double
int sugg = (suggestedOrderQty ?: 0) as int
if (rop > 0) {
    def org = organizationPartyId
    def pid = productId
    def todaySql = alertDate ?: java.sql.Date.valueOf(ec.user.nowTimestamp.toLocalDateTime().toLocalDate())
    def pn = productName ?: pid
    double soh = 0.0; boolean tracked = false; List trackedAssetIds = []
    ec.entity.find("mantle.product.asset.Asset").condition("productId", pid).condition("ownerPartyId", org)
        .selectField("assetId").selectField("quantityOnHandTotal").selectField("hasQuantity").list().each {
            soh += ((it.quantityOnHandTotal ?: 0) as double)
            if (it.hasQuantity == 'Y') { tracked = true; trackedAssetIds.add(it.assetId) }
        }
    // ZE-DF-002/003: alert only for a quantity-tracked product; the exact-0 case only when the lot has
    // AssetDetail ledger history (maintained down to a real stockout) vs a never-counted imported zero.
    boolean maintainedStockout = false
    if (tracked && soh <= 0 && trackedAssetIds) {
        maintainedStockout = ec.entity.find("mantle.product.asset.AssetDetail").condition("assetId", "in", trackedAssetIds).count() > 0
    }
    if (tracked && (soh > 0 || maintainedStockout)) {
        String rdir = null
        if (soh <= 0) rdir = "Critical"
        else if (soh <= ss) rdir = "Critical"
        else if (soh <= rop) rdir = "Reorder"
        else if (soh <= rop * 1.2) rdir = "LowStock"
        if (rdir != null) {
            String lvl = (soh <= 0) ? "out of stock" : (rdir == "Critical" ? "critically low" : (rdir == "Reorder" ? "at the reorder point" : "getting low"))
            String rmsg = "Stock of '" + pn + "' is " + lvl + ": " + ((int)Math.round(soh)) + " units on hand vs a reorder point of " + ((int)Math.round(rop)) + " units (safety stock " + ((int)Math.round(ss)) + "). Suggested order about " + sugg + " units."
            // ZE-DF-004: severity rank so a same-day alert ESCALATES, never downgrades.
            int newSev = (soh <= 0) ? 4 : (rdir == "Critical" ? 3 : (rdir == "Reorder" ? 2 : 1))
            def rdup = ec.entity.find("zenith.erp.inventory.DemandAlert").condition("productId", pid).condition("alertDate", todaySql).condition("alertType", "Reorder").list()
            def exAlert = rdup ? rdup[0] : null
            int exSev = 0
            if (exAlert != null) { double exSoh = (exAlert.stockOnHand ?: 0) as double; exSev = (exSoh <= 0) ? 4 : (exAlert.direction == "Critical" ? 3 : (exAlert.direction == "Reorder" ? 2 : 1)) }
            boolean doNotify = false
            if (exAlert == null) {
                ec.service.sync().name("create#zenith.erp.inventory.DemandAlert").parameters([
                    organizationPartyId: org, productId: pid, productName: pn, alertDate: todaySql, alertType: "Reorder", direction: rdir,
                    reorderPoint: rop, stockOnHand: soh, message: rmsg, statusId: "AlertNew", createdStamp: ec.user.nowTimestamp
                ]).call()
                alerted = true; doNotify = true
            } else if (newSev > exSev) {
                // worsened within the day: upgrade the SAME row + re-surface (AlertNew) + re-notify.
                // direct .update() bypasses the status-flow service check (same as acknowledgeAlert). equal/lower = leave it.
                exAlert.direction = rdir; exAlert.stockOnHand = soh; exAlert.reorderPoint = rop
                exAlert.message = rmsg; exAlert.statusId = "AlertNew"; exAlert.update()
                alerted = true; doNotify = true
            }
            direction = rdir
            if (doNotify) {
                try {
                    def uids = ec.entity.find("moqui.security.UserPreference").condition("preferenceKey","ACTIVE_ORGANIZATION").condition("preferenceValue", org).selectField("userId").list().collect { it.userId }.unique()
                    for (uid in uids) {
                        def nm = ec.makeNotificationMessage().topic("DemandAlert").title("Reorder alert: " + pn).message([productName: pn, type: "Reorder", level: rdir, stockOnHand: (int)Math.round(soh), reorderPoint: (int)Math.round(rop), text: rmsg])
                        nm.userId(uid); nm.send()
                    }
                } catch (Exception ne2) { ec.logger.warn("Reorder notify failed: " + ne2.message) }
            }
        }
    }
}

