    def today = ec.user.nowTimestamp.toLocalDateTime().toLocalDate()
    def todaySql = java.sql.Date.valueOf(today)
    // ZE-DF-007/008: gate each tenant by whether it is open right now (IST) - Store operating hours if
    // configured (source of truth), else the per-tenant CompanySettings window (default 8-22). Once per org.
    def orgAllowed = [:]   // org -> boolean, computed once per org per run
    int skippedClosed = 0
    // today's stored forecasts that carry a positive reorder point (cheap: one indexed read, no forecast math)
    def fcRows = ec.entity.find("zenith.erp.inventory.DemandForecast").condition("periodStart", todaySql).condition("reorderPoint", ">", 0).list()
    for (fcRow in fcRows) {
        def prod = ec.entity.find("mantle.product.Product").condition("productId", fcRow.productId).useCache(true).one()
        def owner = prod?.ownerPartyId
        if (!owner) continue
        if (organizationPartyId && owner != organizationPartyId) continue
        if (!orgAllowed.containsKey(owner)) {
            def oc = ec.service.sync().name("zenith.inventory.AdvancedForecastServices.check#OrgReorderOpen").parameters([organizationPartyId: owner]).call()
            orgAllowed[owner] = (oc?.open == true)
        }
        if (!orgAllowed[owner]) { skippedClosed++; continue }
        checked++
        def rout = ec.service.sync().name("zenith.inventory.AdvancedForecastServices.check#ProductReorder").parameters([
            organizationPartyId: owner, productId: fcRow.productId, productName: (prod.productName ?: fcRow.productId),
            reorderPoint: fcRow.reorderPoint, safetyStock: fcRow.safetyStock, suggestedOrderQty: fcRow.suggestedOrderQty, alertDate: todaySql
        ]).call()
        if (rout?.alerted) raised++
    }
    productsChecked = checked; alertsRaised = raised
    summary = "Reorder re-check: " + checked + " product(s) compared to stock-on-hand, " + raised + " alert(s) raised or escalated" + (skippedClosed > 0 ? (" (" + skippedClosed + " skipped, outside business hours)") : "") + "."
    ec.logger.info(summary)
} catch (Exception e) {
    ec.logger.error("cycle#ReorderCheck failed: " + e.message, e)
    summary = "Reorder re-check hit an error after " + checked + " product(s): " + e.message
    productsChecked = checked; alertsRaised = raised
} finally { if (!_d) ec.artifactExecution.enableAuthz() }

