open = false; source = 'settings'
def now = ec.user.nowTimestamp.toLocalDateTime()   // IST (container/scheduler run Asia/Kolkata)
int nowMin = now.getHour() * 60 + now.getMinute()
int nowHour = now.getHour()
def dowNames = ['Mon','Tue','Wed','Thu','Fri','Sat','Sun']
String dowStr = dowNames[now.getDayOfWeek().getValue() - 1]   // Mon=1 .. Sun=7
def todayDate = java.sql.Date.valueOf(now.toLocalDate())

def toMin = { s ->
    if (!s) return null
    try { def p = s.toString().trim().split(':'); int h = Integer.parseInt(p[0].trim()); int m = (p.length > 1 ? Integer.parseInt(p[1].trim()) : 0); return (h * 60 + m) as Integer }
    catch (Exception e) { return null }
}
def within = { Integer o, Integer c ->
    if (o == null || c == null) return null
    if (o == c) return true                          // 24h
    if (o < c) return (nowMin >= o && nowMin < c)
    return (nowMin >= o || nowMin < c)               // wraps midnight
}

// ---- SOURCE OF TRUTH: Store operating hours, when the org has any store with hours defined for today ----
try {
    def stores = ec.entity.find("zenith.erp.stores.Store").condition("organizationPartyId", organizationPartyId)
        .disableAuthz().selectField("storeId").selectField("statusId").list()
    boolean anyDefined = false; boolean openNow = false
    for (st in stores) {
        if (st.statusId != null && st.statusId != 'StActive') continue   // skip inactive/closed/renovation
        String sid = st.storeId
        def hol = ec.entity.find("zenith.erp.stores.StoreHoliday").condition("storeId", sid).condition("holidayDate", todayDate).disableAuthz().one()
        if (hol != null) {                            // holiday overrides the weekly hours for today
            anyDefined = true
            if (within(toMin(hol.openTime), toMin(hol.closeTime)) == true) openNow = true
            continue                                  // blank holiday times => closed today
        }
        def oh = ec.entity.find("zenith.erp.stores.StoreOperatingHours").condition("storeId", sid).condition("dayOfWeek", dowStr).disableAuthz().one()
        if (oh != null) {
            anyDefined = true
            if (oh.isClosed != 'Y' && within(toMin(oh.openTime), toMin(oh.closeTime)) == true) openNow = true
        }
    }
    if (anyDefined) { open = openNow; source = 'store'; return }
} catch (Exception e) {
    ec.logger.warn("check#OrgReorderOpen: store-hours lookup failed for " + organizationPartyId + ", falling back to settings: " + e.message)
}

// ---- FALLBACK: per-tenant CompanySettings window (default 8-22 IST) ----
