int oh2 = (cfg?.openHour ?: 8) as int; int ch2 = (cfg?.closeHour ?: 22) as int
boolean w2
if (oh2 == ch2) w2 = true
else if (oh2 < ch2) w2 = (nowHour >= oh2 && nowHour < ch2)
else w2 = (nowHour >= oh2 || nowHour < ch2)
open = w2; source = 'settings'

