        int tcnt=Math.min(4,cvPeriods-1); double sumAbs=0.0; double sumAct=0.0
        for (int p=cvPeriods-tcnt; p<cvPeriods; p++){
            int trainEnd=p*7; if(trainEnd<7) continue
            // back-test the SAME damped-trend-shrunk-to-mean model the forecast uses, scored by WAPE (ZE-CP-E-02c)
            def ff=fitC(trainEnd); double fi=(double)ff[0]; double fsl2=(double)ff[1]; double[] fdf=(double[])ff[2]; double fmn=(double)ff[3]
            double fL=fi+fsl2*(trainEnd-1)
            double predTot=0.0, actTot=0.0; def pc=minD.plusDays(trainEnd)
            for (int i=trainEnd; i<trainEnd+7 && i<n; i++){ int dw=pc.getDayOfWeek().getValue()%7; int hstep=i-trainEnd+1; double fdamp=_phi*(1.0-Math.pow(_phi,hstep))/(1.0-_phi); double flvl=Math.max(0.0,fL+fsl2*fdamp); double fbase=0.5*flvl+0.5*fmn; predTot+=Math.max(0.0,fbase*fdf[dw]); actTot+=series[i]; pc=pc.plusDays(1) }
            sumAbs+=Math.abs(actTot-predTot); sumAct+=actTot
        }
        if (sumAct>0){ double wape=sumAbs/sumAct; confidence=Math.max(1,Math.min(96,(int)Math.round(100.0*(1.0-wape)))) }
    }
    def trendTxt = slope>0.02?"rising":(slope<-0.02?"declining":"stable")
    // plain-language reliability band (ZE-CP-E-02c)
    def confBand = { Integer c -> c == null ? null : (c >= 75 ? "high" : (c >= 55 ? "good" : (c >= 40 ? "moderate" : (c >= 25 ? "low" : "very rough")))) }
    res = [categoryName: catNm, products: ownedPids.size(), historyDays: n, avgDailyDemand: (Math.round(mean*100)/100.0), trendPerDay: (Math.round(slope*100)/100.0), peakWeekday: dowNames[peakDow], horizonDays: horizon, forecastDemand: (int)Math.round(fTotal), reorderPoint: (int)Math.round(rop), safetyStock: (int)Math.round(safety), confidencePct: confidence]
    summary = "Category '" + catNm + "' (" + ownedPids.size() + " products): expect about " + ((int)Math.round(fTotal)) + " units of total demand over the next " + horizon + " days (around " + String.format("%.1f", fTotal / (double) horizon) + "/day, " + trendTxt + " trend, busiest on " + dowNames[peakDow] + "). " + (confidence != null ? ("Back-tested confidence about " + confidence + "% (" + confBand(confidence) + "). ") : "") + "Based on " + n + " days of sales."
    result = res
} catch (Exception e) { ec.logger.error("forecast#CategoryDemand failed: " + e.message, e); summary = "The category forecast could not be completed."; result = res } finally { if (!_d) ec.artifactExecution.enableAuthz() }
